#!/usr/bin/env python3
"""Generates seeds/001_ecma_licensed_providers.sql from the public ECMA-licensed provider directory
(https://www.aksion.et/data-intelligence/service-providers, cross-checked against https://ecma.gov.et/licensee-category/...).
Fields ECMA does not publish (licence number, email, website, CEO) are left blank rather than guessed.
"""
def q(s): return "$q$" + s + "$q$"
IB, SD, SA = "Investment Bank", "Securities Dealer", "Securities Investment Advisor"
SERVICES = {
  IB: ["Underwriting", "Issue Management", "Corporate Finance Advisory", "Securities Dealing"],
  SD: ["Securities Dealing", "Securities Brokerage on ESX"],
  SA: ["Investment Advice", "Corporate Securities Advisory"],
}
BLURB = {
  IB: "Licensed by the Ethiopian Capital Market Authority (ECMA) as an investment bank, able to arrange and underwrite securities offerings and advise issuers on listing on the Ethiopian Securities Exchange (ESX).",
  SD: "Licensed by the Ethiopian Capital Market Authority (ECMA) as a securities dealer, enabling investors to buy and sell securities on the Ethiopian Securities Exchange (ESX).",
  SA: "Licensed by the Ethiopian Capital Market Authority (ECMA) as a corporate securities investment advisor, advising issuers and investors on capital-market transactions.",
}
# name, category, licence date (ISO), phone, address
rows = [
 ("Awash Capital S.C.", IB, "2025-11-19", "+251115269987", "Lideta Sub-city, Woreda 07, Nile Insurance HQ Building, 16th Floor, Addis Ababa"),
 ("BDO Consulting PLC", SA, "2026-02-12", "+251116631196", "Bole Sub-city, Woreda 03, Tropical Mall Building, 11th Floor, Addis Ababa"),
 ("BluFin Capital Advisory PLC", SA, "2026-07-10", "+251995884955", "Jomo Kenyatta St., Kidus Complex, 3rd Floor, Addis Ababa"),
 ("CBE Capital Investment Bank S.C.", IB, "2025-03-21", "", "Commercial Bank of Ethiopia Headquarters, Main Building, 1st Floor, Addis Ababa"),
 ("D & T Management Consulting P.L.C.", SA, "2024-03-29", "", "Minaye Corporate Office Park, 2nd Floor, Addis Ababa"),
 ("Equation Securities Investment Advisor P.L.C.", SA, "2025-03-21", "+251944252272", "Afework Building, 1st Floor, Office No. 107, Addis Ababa"),
 ("Ethio Capital P.L.C.", SA, "2025-03-12", "+0115579085", "Kirkos Sub-city, Woreda 10, Legahar, ORDA Tower, 10th Floor, Offices 1001 & 1002, Addis Ababa"),
 ("Ethio-Fidelity Securities S.C.", SD, "2025-03-21", "+251115578397", "Sengatera Building, 13th Floor, Mexico Area, Addis Ababa"),
 ("First Addis Investment Bank PLC", IB, "2025-09-30", "+251911686947", "Meskel Flower, Central Printing Press Building, 6th Floor, Addis Ababa"),
 ("Gadaa Securities Dealer S.C.", SD, "2025-12-24", "+251904651784", "Lideta Sub-city, Woreda 07, Nile Insurance HQ Building, 16th Floor, Addis Ababa"),
 ("HST Investment Advisors P.L.C.", SA, "2025-03-21", "+251115527666", "Mina Building, 2nd and 4th Floors, Ethio-China Friendship Avenue, Addis Ababa"),
 ("Ignite Capital PLC", SA, "2025-09-30", "+251115248011", "Kirkos Sub-city, Woreda 03, Tebaber Berta Building, 7th Floor, Office 702D, Addis Ababa"),
 ("Lumina Capital PLC", SA, "2026-07-10", "+251964748888", "Jomo Kenyatta St., Kidus Complex, 2nd Floor, Addis Ababa"),
 ("Prime Capital S.C", IB, "2026-04-21", "+251111137147", "Bole Sub-city, Bole Road, Abyssinia Real Estate Building, 12th Floor, Addis Ababa"),
 ("PrizeWorth Investment Bank S.C", IB, "2026-07-10", "+251115575054", "Africa Avenue St., behind Bole Printing, Ethiobest Real Estate Building, 3rd Floor, Addis Ababa"),
 ("ProInvest Capital PLC", SA, "2025-10-31", "+251911527050", "Bole Sub-city, Woreda 08, Dembel City Center Building, 3rd Floor, Office TF-015, Addis Ababa"),
 ("Siinqee Investment Bank S.C.", IB, "2025-12-31", "+251995023267", "Kirkos Sub-city, Woreda 08, Nega Mall Building, 7th Floor, Addis Ababa"),
 ("Wegagen Capital Investment Bank S.C.", IB, "2025-03-21", "+251111309928", "Wegagen Tower, 10th Floor, Ras Mekonnen Street, Addis Ababa"),
 ("Zuri Capital S.C.", SA, "2025-09-30", "+251912012146", "Kirkos Sub-city, Gotera, Kas Tower Building, 11th Floor, Addis Ababa"),
 ("i-Capital Africa Institute P.L.C.", SA, "2024-11-25", "+251911629011", "Elsi Building, 6th Floor, Arat Kilo, Arada Sub-city, Addis Ababa"),
]
out = ["-- Generated by seeds/gen_csps.py (ECMA-licensed capital market service providers). Idempotent.", "BEGIN;",
       "DELETE FROM capital_service_providers WHERE name='Ethio-Fidelity Securities S.C.' AND license_number LIKE 'MIGRATED-%';",
       "DELETE FROM capital_service_providers WHERE name='Wegagen Capital Investment Bank' AND license_number LIKE 'MIGRATED-%';"]
for name, cat, d, phone, addr in rows:
    svc = "{" + ",".join('"%s"' % s for s in SERVICES[cat]) + "}"
    desc = BLURB[cat]
    # existing curated rows (CBE Capital, Ethio-Fidelity) keep richer text, contacts and services; we only normalise the licence facts
    out.append(f"""UPDATE capital_service_providers SET category={q(cat)}, status='Active', registration_date='{d}', updated_at=now(),
  license_number=CASE WHEN license_number IN ('-','') OR license_number LIKE 'MIGRATED-%' THEN {q('Not published · ' + name)} ELSE license_number END,
  phone=CASE WHEN phone='' THEN {q(phone)} ELSE phone END, head_office=CASE WHEN head_office='' THEN {q(addr)} ELSE head_office END
WHERE name={q(name)} AND deleted_at IS NULL;""")
    out.append(f"""INSERT INTO capital_service_providers (name, license_number, category, status, registration_date, services, paid_up_capital, phone, head_office, description, created_at, updated_at)
SELECT {q(name)}, {q('Not published · ' + name)}, {q(cat)}, 'Active', '{d}', '{svc}', 0, {q(phone)}, {q(addr)}, {q(desc)}, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM capital_service_providers WHERE name={q(name)} AND deleted_at IS NULL);""")
out.append("COMMIT;")
open("001_ecma_licensed_providers.sql", "w").write("\n".join(out) + "\n")
print(len(rows), "providers")
